import json
import sys

target_type_raw = sys.argv[1]
organization_raw = sys.argv[2]
target_name_raw = sys.argv[3]
version_raw = sys.argv[4]
image_source_raw = sys.argv[5]
server_mode_raw = sys.argv[6]
excluded_components_raw = sys.argv[8]
excluded_pids_raw = sys.argv[9]
fabric_evacuation_raw = sys.argv[11]
psu_raw = sys.argv[13]
pdb_raw = sys.argv[14]
skip_io_raw = sys.argv[15]
wait_raw = sys.argv[16]
wait_timeout_raw = sys.argv[17]

targetType = target_type_raw.strip()
organizationName = organization_raw.strip()
targetName = target_name_raw.strip()
firmwareVersion = version_raw.strip()
image_source = image_source_raw.strip()
server_mode = server_mode_raw.strip()
excluded_components_text = excluded_components_raw.strip()
excluded_pids_text = excluded_pids_raw.strip()
errors = []

for raw, clean, label in ((target_type_raw, targetType, "Target Type"), (organization_raw, organizationName, "Device Organization"), (target_name_raw, targetName, "Target Name"), (version_raw, firmwareVersion, "Firmware Version"), (image_source_raw, image_source, "Image Source"), (server_mode_raw, server_mode, "Server Upgrade Mode"), (excluded_components_raw, excluded_components_text, "Excluded Components"), (excluded_pids_raw, excluded_pids_text, "Excluded Component PIDs")):
    if raw != clean:
        errors.append(label + " must not contain surrounding whitespace.")

def strict_bool(value, label):
    normalized = str(value).strip().lower()
    if normalized not in ("true", "false"):
        errors.append(label + " must be a boolean.")
        return False
    return normalized == "true"

def strict_int(value, label):
    try:
        parsed = int(value)
    except Exception:
        errors.append(label + " must be an integer.")
        return 0
    if str(parsed) != str(value):
        errors.append(label + " must use canonical integer syntax.")
    return parsed

enable_fabric_evacuation = strict_bool(fabric_evacuation_raw, "Enable Fabric Evacuation")
enable_psu_upgrade = strict_bool(psu_raw, "Enable PSU Upgrade")
enable_pdb_fpga_upgrade = strict_bool(pdb_raw, "Enable PDB FPGA Upgrade")
skip_wait_for_io = strict_bool(skip_io_raw, "Skip Wait for I/O Connectivity")
waitForCompletion = strict_bool(wait_raw, "Wait for Completion")
waitTimeoutSeconds = strict_int(wait_timeout_raw, "Wait Timeout Seconds")

if targetType not in {"Server", "UCS-X Chassis", "Domain"}:
    errors.append("Target Type must exactly match Server, UCS-X Chassis, or Domain.")
if image_source != "Cisco Repository":
    errors.append("Image Source must be exactly Cisco Repository.")

def validate_odata(value, label, maximum):
    if not value or len(value) > maximum or any(ord(char) < 32 or char in "&?#%" for char in value):
        errors.append(label + " must contain 1-" + str(maximum) + " characters and no control or URL query-delimiter characters.")

validate_odata(organizationName, "Device Organization", 64)
validate_odata(targetName, "Target Name", 128)
validate_odata(firmwareVersion, "Firmware Version", 128)

excluded_components = []
if excluded_components_text:
    try:
        excluded_components = json.loads(excluded_components_text)
    except Exception:
        errors.append("Excluded Components must be valid JSON.")
        excluded_components = []
    if not isinstance(excluded_components, list) or any(not isinstance(value, str) or not value or value != value.strip() for value in excluded_components):
        errors.append("Excluded Components must be a JSON array of exact non-empty strings.")
        excluded_components = []
    elif len(excluded_components) != len(set(excluded_components)):
        errors.append("Excluded Components must not contain duplicates.")
if "none" in excluded_components and len(excluded_components) != 1:
    errors.append("Excluded Components value none is mutually exclusive with other values.")

excluded_pid_object = None
if excluded_pids_text:
    try:
        excluded_pid_object = json.loads(excluded_pids_text)
    except Exception:
        errors.append("Excluded Component PIDs must be valid JSON.")
    allowed_keys = {"ExcludeLocalDiskList", "ExcludeStorageControllerList"}
    if excluded_pid_object is not None:
        if not isinstance(excluded_pid_object, dict) or not excluded_pid_object or set(excluded_pid_object) - allowed_keys:
            errors.append("Excluded Component PIDs must contain only supported non-empty PID arrays.")
            excluded_pid_object = None
        else:
            for key, values in excluded_pid_object.items():
                if not isinstance(values, list) or not values or any(not isinstance(value, str) or not value or value != value.strip() or len(value) > 128 for value in values) or len(values) != len(set(values)):
                    errors.append(key + " must be a non-empty array of unique exact strings no longer than 128 characters.")
                    excluded_pid_object = None
                    break

domain_defaults_changed = enable_fabric_evacuation is not True or enable_psu_upgrade or enable_pdb_fpga_upgrade or skip_wait_for_io
if targetType == "Server":
    allowed = {"none", "local-disk", "drives-except-boot-drives", "storage-controller", "storage-sasexpander", "storage-u2"}
    if server_mode not in ("Start Immediately", "Mount Only"):
        errors.append("Server Upgrade Mode must be Start Immediately or Mount Only for Server.")
    if any(value not in allowed for value in excluded_components):
        errors.append("Excluded Components contains a value not supported by firmware.Upgrade.")
    if domain_defaults_changed:
        errors.append("Domain-only upgrade options must retain defaults for Server.")
elif targetType == "UCS-X Chassis":
    allowed = {"none", "local-disk", "psu", "xfm"}
    if server_mode != "Start Immediately":
        errors.append("Server Upgrade Mode must retain Start Immediately for UCS-X Chassis.")
    if any(value not in allowed for value in excluded_components):
        errors.append("Excluded Components contains a value not supported by firmware.ChassisUpgrade.")
    if excluded_pid_object is not None:
        errors.append("Excluded Component PIDs is not supported by firmware.ChassisUpgrade.")
    if domain_defaults_changed:
        errors.append("Domain-only upgrade options must retain defaults for UCS-X Chassis.")
elif targetType == "Domain":
    if server_mode != "Start Immediately" or excluded_components or excluded_pid_object is not None:
        errors.append("Server/chassis-only mode, exclusions, and PID options must retain defaults for Domain.")

if waitForCompletion:
    if waitTimeoutSeconds < 1 or waitTimeoutSeconds > 600:
        errors.append("Wait Timeout Seconds must be from 1 through 600 when Wait for Completion is true.")
elif waitTimeoutSeconds != 0:
    errors.append("Wait Timeout Seconds must remain numeric 0 when Wait for Completion is false.")

escapedOrganizationName = organizationName.replace("'", "''")
escaped_name = targetName.replace("'", "''")
escapedFirmwareVersion = firmwareVersion.replace("'", "''")
targetApiUrl = ""
expectedTargetObjectType = ""
if targetType == "Server":
    expectedTargetObjectType = "compute.PhysicalSummary"
    targetApiUrl = "/api/v1/compute/PhysicalSummaries?$filter=Name eq '" + escaped_name + "' and PermissionResources/any(t:t/Moid eq '{organizationMoid}')&$select=Moid,Name,Model,ManagementMode,SourceObjectType,ObjectType,ClassId,PermissionResources"
elif targetType == "UCS-X Chassis":
    expectedTargetObjectType = "equipment.Chassis"
    targetApiUrl = "/api/v1/equipment/Chasses?$filter=Name eq '" + escaped_name + "' and PermissionResources/any(t:t/Moid eq '{organizationMoid}')&$select=Moid,Name,Model,PlatformType,ObjectType,ClassId,PermissionResources,ExpanderModules&$expand=ExpanderModules($select=Moid,Model,ModuleId,OperState,OperReason,Presence,InventoryReady,ObjectType,ClassId,EquipmentChassis)"
elif targetType == "Domain":
    expectedTargetObjectType = "asset.Target"
    targetApiUrl = "/api/v1/asset/Targets?$filter=Name eq '" + escaped_name + "' and TargetType eq 'UCSFIISM' and Status eq 'Connected' and PermissionResources/any(t:t/Moid eq '{organizationMoid}')&$select=Moid,Name,TargetType,Status,RegisteredDevice,ObjectType,ClassId,PermissionResources"

preparationStatus = "invalid" if errors else "ready"
preparationMessage = " ".join(errors) if errors else "Inputs, branch options, JSON shapes, and exact OData routes were validated."
preparationResultJson = json.dumps({"validated":not errors,"errors":errors,"targetType":targetType,"deviceOrganization":organizationName,"targetName":targetName,"firmwareVersion":firmwareVersion,"imageSource":image_source,"serverUpgradeMode":server_mode,"skipEstimateImpact":False,"excludedComponents":excluded_components,"excludedComponentPids":excluded_pid_object,"enableFabricEvacuation":enable_fabric_evacuation,"switchWaitTimeoutMinutes":0,"enablePsuUpgrade":enable_psu_upgrade,"enablePdbFpgaUpgrade":enable_pdb_fpga_upgrade,"skipWaitForIoPathConnectivity":skip_wait_for_io,"waitForCompletion":waitForCompletion,"waitTimeoutSeconds":waitTimeoutSeconds,"acceptedVersusCompletedSemantics":True,"ciscoRepositoryOnly":True}, separators=(",", ":"))
helperReady = preparationStatus in ("invalid", "ready") and bool(preparationMessage and preparationResultJson) and (preparationStatus != "ready" or bool(targetApiUrl and expectedTargetObjectType))

import json
import re
import sys

payload = json.loads(sys.argv[1])
prepared = json.loads(sys.argv[2])
organizationMoid = sys.argv[3]
targetType = str(prepared.get("targetType") or "")
expectedName = str(prepared.get("targetName") or "")
expectedObjectType = {"Server":"compute.PhysicalSummary","UCS-X Chassis":"equipment.Chassis","Domain":"asset.Target"}.get(targetType, "")
firmwareVersion = str(prepared.get("firmwareVersion") or "")
escapedFirmwareVersion = firmwareVersion.replace("'", "''")
values = payload.get("Results")
if not isinstance(values, list):
    raise ValueError("Target response is missing a Results array")

def safe_moid(value):
    return isinstance(value, str) and re.fullmatch(r"[0-9a-fA-F]{24}", value) is not None

def relation_matches(rel, moid, objectType):
    return isinstance(rel, dict) and rel.get("Moid") == moid and rel.get("ObjectType") == objectType and rel.get("ClassId") in (None, "mo.MoRef", objectType)

def organization_matches(item):
    permissions = item.get("PermissionResources")
    matches = [value for value in permissions if relation_matches(value, organizationMoid, "organization.Organization")] if isinstance(permissions, list) else []
    return len(matches) == 1

targetMoid = ""
targetModel = ""
sourceObjectType = ""
managementMode = ""
distributableType = ""
registeredDeviceMoid = ""
networkElements = []
imageApiUrl = ""
activeUpgradeApiUrl = ""
domainElementsApiUrl = ""
readinessCaveats = []
xfmUpgradeOption = "none"
normalizedExclusions = prepared.get("excludedComponents") if isinstance(prepared.get("excludedComponents"), list) else []
xfmTopology = {"supportedModel":"UCSX-FS-9516","healthyPair":False,"modules":[]}

if len(values) == 0:
    targetStatus = "not-found"
    targetMessage = "No exact organization-scoped target matched Target Name."
elif len(values) > 1:
    targetStatus = "ambiguous"
    targetMessage = "Multiple organization-scoped targets matched Target Name."
else:
    item = values[0]
    problems = []
    if not isinstance(item, dict):
        problems.append("Target result is not an object.")
    else:
        moid = str(item.get("Moid") or "")
        if not safe_moid(moid):
            problems.append("Target Moid must be a concrete 24-character hexadecimal identifier.")
        if item.get("Name") != expectedName:
            problems.append("Target Name does not exactly match the requested name.")
        if item.get("ObjectType") != expectedObjectType or item.get("ClassId") != expectedObjectType:
            problems.append("Target discriminators do not match the selected target route.")
        if not organization_matches(item):
            problems.append("Target must contain exactly one matching organization permission relationship.")

        if targetType == "Server":
            model = item.get("Model")
            mode = item.get("ManagementMode")
            source = item.get("SourceObjectType")
            if not isinstance(model, str) or not model:
                problems.append("PhysicalSummary Model is required for image compatibility.")
            if mode not in ("Intersight", "IntersightStandalone", "UCSM"):
                problems.append("PhysicalSummary ManagementMode is not a documented server mode.")
            if source not in ("compute.Blade", "compute.RackUnit"):
                problems.append("PhysicalSummary SourceObjectType must be compute.Blade or compute.RackUnit.")
            if mode in ("Intersight", "IntersightStandalone"):
                distributableType = "IMMHOST"
            elif mode == "UCSM" and source == "compute.Blade":
                distributableType = "UMMBLADE"
            elif mode == "UCSM" and source == "compute.RackUnit":
                distributableType = "UMMRACK"
            targetModel = model or ""
            managementMode = mode or ""
            sourceObjectType = source or ""
            imageApiUrl = "/api/v1/firmware/Distributables?$filter=Version eq '" + escapedFirmwareVersion + "'&$select=Moid,Version,Model,SupportedModels,ImageType,PlatformType,Vendor,Origin,ObjectType,ClassId,Tags"
            activeUpgradeApiUrl = "/api/v1/firmware/Upgrades?$filter=Server.Moid eq '" + moid + "' and (Status eq 'NONE' or Status eq 'IN_PROGRESS')&$top=2&$select=Moid,Status,ObjectType,ClassId,Server"
        elif targetType == "UCS-X Chassis":
            model = item.get("Model")
            if not isinstance(model, str) or not model.startswith("UCSX-"):
                problems.append("UCS-X Chassis requires an exact equipment.Chassis Model beginning UCSX-.")
            targetModel = model or ""
            expanded = item.get("ExpanderModules")
            if not isinstance(expanded, list):
                problems.append("UCS-X Chassis must expand ExpanderModules.")
                expanded = []
            realModules = []
            equippedBlanks = []
            for module in expanded:
                if not isinstance(module, dict):
                    problems.append("Every expanded ExpanderModule must be an object.")
                    continue
                moduleMoid = module.get("Moid")
                moduleModel = module.get("Model")
                presence = str(module.get("Presence") or "").lower()
                if not safe_moid(moduleMoid):
                    problems.append("Every expanded ExpanderModule requires a concrete Moid.")
                if module.get("ObjectType") != "equipment.ExpanderModule" or module.get("ClassId") != "equipment.ExpanderModule":
                    problems.append("Expanded ExpanderModule discriminators are invalid.")
                if not relation_matches(module.get("EquipmentChassis"), moid, "equipment.Chassis"):
                    problems.append("Every expanded ExpanderModule must relate to the selected chassis.")
                summary = {"Moid":moduleMoid,"Model":moduleModel,"ModuleId":module.get("ModuleId"),"Presence":module.get("Presence"),"OperState":module.get("OperState"),"InventoryReady":module.get("InventoryReady")}
                xfmTopology["modules"].append(summary)
                if moduleModel == "UCSX-FS-9516":
                    realModules.append(module)
                elif presence == "equipped" and moduleModel == "UCSX-9508-RBLK":
                    equippedBlanks.append(module)
                elif presence == "equipped":
                    problems.append("Unknown equipped ExpanderModule model " + str(moduleModel) + " is not in the proven XFM topology set.")
            if realModules and equippedBlanks:
                problems.append("Mixed equipped XFM and rear-blank topology is not safe for automatic XFM upgrade.")
            if realModules:
                if len(realModules) != 2 or {module.get("ModuleId") for module in realModules} != {1, 2}:
                    problems.append("Equipped UCSX-FS-9516 topology must contain exactly ModuleId 1 and 2.")
                for module in realModules:
                    reasons = module.get("OperReason")
                    if str(module.get("Presence") or "").lower() != "equipped" or module.get("OperState") != "OK" or module.get("InventoryReady") is not True or not isinstance(reasons, list) or any(reason not in ("OK",) for reason in reasons):
                        problems.append("Both UCSX-FS-9516 modules must be equipped, inventory-ready, operationally OK, and free of health reasons.")
                        break
                if not problems:
                    xfmTopology["healthyPair"] = True
            normalizedExclusions = [] if normalizedExclusions == ["none"] else list(normalizedExclusions)
            if xfmTopology["healthyPair"] and "xfm" not in normalizedExclusions:
                xfmUpgradeOption = "partial-shutdown"
            else:
                xfmUpgradeOption = "none"
                if "xfm" not in normalizedExclusions:
                    normalizedExclusions.append("xfm")
            imageApiUrl = "/api/v1/firmware/Distributables?$filter=Version eq '" + escapedFirmwareVersion + "'&$select=Moid,Version,Model,SupportedModels,ImageType,PlatformType,Vendor,Origin,ObjectType,ClassId,Tags"
            activeUpgradeApiUrl = "/api/v1/firmware/ChassisUpgrades?$filter=Chassis.Moid eq '" + moid + "' and (Status eq 'NONE' or Status eq 'IN_PROGRESS')&$top=2&$select=Moid,Status,ObjectType,ClassId,Chassis"
        elif targetType == "Domain":
            if item.get("TargetType") != "UCSFIISM":
                problems.append("Domain asset.Target TargetType must be UCSFIISM.")
            if item.get("Status") != "Connected":
                problems.append("Domain asset.Target Status must be Connected.")
            registration = item.get("RegisteredDevice")
            if not isinstance(registration, dict) or not safe_moid(registration.get("Moid")) or registration.get("ObjectType") != "asset.DeviceRegistration" or registration.get("ClassId") not in (None, "mo.MoRef", "asset.DeviceRegistration"):
                problems.append("Domain asset.Target must expose a concrete RegisteredDevice relationship.")
            else:
                registeredDeviceMoid = registration["Moid"]
                domainElementsApiUrl = "/api/v1/network/Elements?$filter=RegisteredDevice/Moid eq '" + registeredDeviceMoid + "' and SwitchType eq 'FabricInterconnect' and PermissionResources/any(t:t/Moid eq '" + organizationMoid + "')&$select=Moid,Model,SwitchId,SwitchType,RegisteredDevice,ObjectType,ClassId,PermissionResources"

        if problems:
            targetStatus = "invalid"
            targetMessage = " ".join(problems)
        elif targetType == "Domain":
            targetStatus = "domain-pending"
            targetMoid = item["Moid"]
            targetMessage = "Connected IMM domain identity was validated; resolving its exact Fabric Interconnect A/B pair."
        else:
            targetStatus = "exact"
            targetMoid = item["Moid"]
            targetMessage = "Exactly one organization-scoped firmware target and branch-specific inventory were validated."

targetResultJson = json.dumps({"status":targetStatus,"message":targetMessage,"targetType":targetType,"targetName":expectedName,"targetMoid":targetMoid or None,"targetObjectType":expectedObjectType,"targetModel":targetModel or None,"managementMode":managementMode or None,"sourceObjectType":sourceObjectType or None,"distributableType":distributableType or None,"registeredDeviceMoid":registeredDeviceMoid or None,"networkElements":networkElements,"excludedComponents":normalizedExclusions,"xfmUpgradeOption":xfmUpgradeOption,"xfmTopology":xfmTopology if targetType == "UCS-X Chassis" else None,"activeUpgradeApiUrl":activeUpgradeApiUrl or None,"firmwareVersion":firmwareVersion,"readinessCaveats":readinessCaveats}, separators=(",",":"))
helperReady = targetStatus in ("not-found","ambiguous","invalid","domain-pending","exact") and bool(targetMessage and targetResultJson) and (targetStatus not in ("exact","domain-pending") or bool(targetMoid)) and (targetStatus != "exact" or bool(imageApiUrl and activeUpgradeApiUrl)) and (targetStatus != "domain-pending" or bool(domainElementsApiUrl and registeredDeviceMoid))

import json
import re
import sys
payload = json.loads(sys.argv[1])
target = json.loads(sys.argv[2])
prepared = json.loads(sys.argv[3])
values = payload.get("Results")
if not isinstance(values, list):
    raise ValueError("Active firmware response is missing a Results array")

def safe_moid(value):
    return isinstance(value, str) and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._~-]{0,127}", value) is not None

def relation_matches(rel, moid, objectType):
    return isinstance(rel, dict) and rel.get("Moid") == moid and rel.get("ObjectType") == objectType and rel.get("ClassId") in (None, "mo.MoRef", objectType)

targetType = prepared.get("targetType")
expectedType = {"Server": "firmware.Upgrade", "UCS-X Chassis": "firmware.ChassisUpgrade", "Domain": "firmware.SwitchUpgrade"}.get(targetType)
problems = []
active = []
for index, item in enumerate(values):
    if not isinstance(item, dict):
        problems.append("Existing firmware result " + str(index) + " is not an object.")
        continue
    if not safe_moid(item.get("Moid")) or item.get("ObjectType") != expectedType or item.get("ClassId") != expectedType:
        problems.append("Existing firmware result " + str(index) + " has invalid identity or discriminators.")
        continue
    status = item.get("Status")
    if status not in ("NONE", "IN_PROGRESS", "SUCCESSFUL", "FAILED", "TERMINATED"):
        problems.append("Existing firmware result " + str(index) + " has an undocumented Status.")
        continue
    if targetType == "Server":
        if not relation_matches(item.get("Server"), target.get("targetMoid"), target.get("sourceObjectType")):
            problems.append("Existing server firmware result does not match the validated concrete server relationship.")
            continue
    elif targetType == "UCS-X Chassis":
        if not relation_matches(item.get("Chassis"), target.get("targetMoid"), "equipment.Chassis"):
            problems.append("Existing chassis firmware result does not match the validated chassis relationship.")
            continue
    elif targetType == "Domain":
        expectedMoids = {entry.get("Moid") for entry in target.get("networkElements", []) if isinstance(entry, dict)}
        returned = item.get("NetworkElements")
        returnedMoids = {entry.get("Moid") for entry in returned if isinstance(entry, dict) and relation_matches(entry, entry.get("Moid"), "network.Element")} if isinstance(returned, list) else set()
        if not isinstance(returned, list) or len(returned) != 2 or returnedMoids != expectedMoids:
            problems.append("Existing switch firmware result does not exactly match the two validated domain FI relationships.")
            continue
    if status in ("NONE", "IN_PROGRESS"):
        active.append({"Moid": item["Moid"], "Status": status, "ObjectType": expectedType})

if problems:
    preflightStatus = "invalid"
    preflightMessage = " ".join(problems)
elif active:
    preflightStatus = "conflict"
    preflightMessage = "The exact target already has " + str(len(active)) + " active NONE/IN_PROGRESS firmware resource(s); no duplicate create was submitted."
else:
    preflightStatus = "clear"
    preflightMessage = "No exact active firmware resource blocks this create. The read-before-create duplicate race remains and is documented."
preflightResultJson = json.dumps({
    "status": preflightStatus,
    "message": preflightMessage,
    "targetType": targetType,
    "targetMoid": target.get("targetMoid"),
    "activeResources": active,
    "bestEffortIdempotencyGuard": True,
    "duplicateRaceRemains": True,
    "requestAccepted": False
}, separators=(",", ":"))
helperReady = preflightStatus in ("invalid", "conflict", "clear") and bool(preflightMessage and preflightResultJson)
